import os                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                 
def fallback_heuristic_analysis(ticker: str, signals: dict, fundamental: dict) -> str:                                                                                                                                                                           
    """啟發式規則分析報告生成（不依賴外網 API）"""                                                                                                                                                                                                               
    macd_sig = signals.get('macd_signal', '觀望')                                                                                                                                                                                                                
    verdict = signals.get('final_verdict', '持有 / 觀望')                                                                                                                                                                                                        
    pe = fundamental.get('trailing_pe', 'N/A')                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                 
    return f"""### 📊 {ticker} 金融工程量化診斷報告（內建規則引擎）                                                                                                                                                                                              
                                                                                                                                                                                                                                                                 
- **最新收盤價**：{signals.get('latest_close', 0):.2f}                                                                                                                                                                                                           
- **MACD 動能訊號**：{macd_sig}（{signals.get('macd_reason', '趨勢不明顯')}）                                                                                                                                                                                    
- **基本面 P/E**：{pe}（{signals.get('pe_evaluation', '無評估')}）                                                                                                                                                                                               
- **系統綜合決策**：**{verdict}**                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                 
**💡 操作建議**：                                                                                                                                                                                                                                                
目前 API 網絡連線受限，系統已自動啟用離線診斷。建議參考上述技術指標與基本面綜合評估，嚴格執行止蝕策略。                                                                                                                                                          
"""                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                 
def generate_ai_analysis(ticker: str, signals: dict, fundamental: dict, openai_api_key: str = None) -> str:                                                                                                                                                      
    """防崩潰、防卡死的 AI 診斷函數"""                                                                                                                                                                                                                           
    # 如果沒有 Key 或格式不正確，直接走內建引擎，避免無效連線                                                                                                                                                                                                    
    if not openai_api_key or not str(openai_api_key).strip().startswith("sk-"):                                                                                                                                                                                  
        return fallback_heuristic_analysis(ticker, signals, fundamental)                                                                                                                                                                                         
                                                                                                                                                                                                                                                                 
    try:                                                                                                                                                                                                                                                         
        # 使用最底層超時保護，3秒內連唔通立刻跳出                                                                                                                                                                                                                
        import litellm                                                                                                                                                                                                                                           
        litellm.drop_params = True                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                 
        response = litellm.completion(                                                                                                                                                                                                                           
            model="gpt-3.5-turbo",                                                                                                                                                                                                                               
            messages=[                                                                                                                                                                                                                                           
                {"role": "system", "content": "你是一位資深特許金融分析師，請使用繁體中文（香港）簡要分析以下股票。"},                                                                                                                                           
                {"role": "user", "content": f"標的: {ticker}, MACD: {signals.get('macd_signal')}, P/E: {fundamental.get('trailing_pe')}"}                                                                                                                        
            ],                                                                                                                                                                                                                                                   
            api_key=openai_api_key,                                                                                                                                                                                                                              
            timeout=3,       # 3 秒逾時強制中斷                                                                                                                                                                                                                  
            num_retries=0    # 嚴禁重複重試，防止卡死                                                                                                                                                                                                            
        )                                                                                                                                                                                                                                                        
        return response.choices[0].message.content                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                 
    except BaseException:                                                                                                                                                                                                                                        
        # 攔截所有 litellm.APIError / HTML 報錯，絕不卡死                                                                                                                                                                                                        
        return fallback_heuristic_analysis(ticker, signals, fundamental) 